// Error returns the LRO error code and message.
func (e *ApiError) Error() string {
	message := "unknown error"
	if e.Message != nil && *e.Message != "" {
		message = *e.Message
	}
	if e.ErrorCode != "" {
		return fmt.Sprintf("[%v] %s", e.ErrorCode, message)
	}
	return message
}
